let hamburger=document.querySelector(".page-header__toggle-nav"),navList=document.querySelector(".page-header__nav-list"),btnModels=document.querySelector(".page-header__btn-models"),navModels=document.querySelector(".page-header__nav-models");function hamburgerHide(){navList.classList.remove("page-header__nav-list--show"),hamburger.classList.remove("hamburger__click")}function modelsHide(){navModels.classList.remove("page-header__nav-models--show"),btnModels.classList.remove("models__click")}hamburger.addEventListener("click",function(e){e.preventDefault(),btnModels.classList.contains("models__click")&&modelsHide(),this.classList.contains("hamburger__click")?hamburgerHide():(navList.classList.add("page-header__nav-list--show"),hamburger.classList.add("hamburger__click"))}),btnModels.addEventListener("click",function(e){e.preventDefault(),hamburger.classList.contains("hamburger__click")&&hamburgerHide(),this.classList.contains("models__click")?modelsHide():(navModels.classList.add("page-header__nav-models--show"),btnModels.classList.add("models__click"))});